 private readonly GpuActivityProbe gpuProbe=new();private DateTimeOffset gpuAt;private bool gpuReading;private string gpuUsage="Not sampled",networkActivity="Warming up";private long? networkReceived,networkSent;private DateTimeOffset networkAt;
 internal async Task SampleGraphicsForValidationAsync(){GpuUsage=await Task.Run(gpuProbe.Read);await Task.Delay(1200);GpuUsage=await Task.Run(gpuProbe.Read);}
 public string GpuUsage{get=>gpuUsage;private set=>Set(ref gpuUsage,value);}
 public string NetworkActivity{get=>networkActivity;private set=>Set(ref networkActivity,value);}
 public string AppliedCount=>History.Where(j=>j.IsActive).Sum(j=>j.Operations.Count(op=>op.State=="applied"))+" verified at last apply";
 public string CurrentPowerPlan=>Operations.FirstOrDefault(o=>o.Id=="power")?.Current??"Not read";
 private async Task SampleExtendedAsync()
 {
  try{var statistics=await Task.Run(()=>System.Net.NetworkInformation.NetworkInterface.GetAllNetworkInterfaces().Where(n=>n.OperationalStatus==System.Net.NetworkInformation.OperationalStatus.Up&&n.NetworkInterfaceType!=System.Net.NetworkInformation.NetworkInterfaceType.Loopback).Select(n=>n.GetIPStatistics()).ToArray());long received=statistics.Sum(s=>s.BytesReceived),sent=statistics.Sum(s=>s.BytesSent);var now=DateTimeOffset.UtcNow;double seconds=(now-networkAt).TotalSeconds;if(networkReceived.HasValue&&seconds>.25&&received>=networkReceived&&sent>=networkSent)NetworkActivity=$"↓ {(received-networkReceived.Value)/seconds/1024:0.0} · ↑ {(sent-networkSent!.Value)/seconds/1024:0.0} KB/s";else NetworkActivity="Warming up / adapter changed";networkReceived=received;networkSent=sent;networkAt=now;}catch(Exception error){logger.Error(error);NetworkActivity="Unavailable";}
  if(gpuReading||(DateTimeOffset.UtcNow-gpuAt).TotalSeconds<30)return;gpuReading=true;gpuAt=DateTimeOffset.UtcNow;
  try{GpuUsage=await Task.Run(gpuProbe.Read);}catch(Exception error){logger.Error(error);GpuUsage="Unavailable";}finally{gpuReading=false;}
 }
 public string ProfileAssessment
 {
  get{if(!Profiles.Contains(Profile))return "Imported profile: inspect its exact queue and capability results.";var document=ResolveProfile(Profile);return string.Join("\n",document.Parameters.Select(p=>{var definition=Catalog.Get(p.Id);var item=Operations.Single(o=>o.Id==p.Id);var blocked=!item.Eligible||p.Id=="power"&&!Plans.Any(plan=>plan.Id==p.Value);return $"{definition.Title}: {(blocked?"Unsupported / unavailable":item.Current==Friendly(p.Id,p.Value)?"Already matches":"Proposed "+Friendly(p.Id,p.Value))} · {definition.Risk}"+(definition.Restart?" · restart may be required":"");}));}
 }
